SELECT  FROM sol_dynamic_form_instance
WHERE tenant_id = #{query.tenantId}
  AND preparation_id = #{query.preparationId}
  AND item_id = #{query.itemId}
  AND id = #{query.formInstanceId}
FOR UPDATE

SELECT  FROM sol_dynamic_form_instance
WHERE tenant_id = #{query.tenantId}
  AND preparation_id = #{query.preparationId}
ORDER BY item_id ASC, form_code ASC, id ASC
FOR UPDATE

mapper.update:
UPDATE sol_dynamic_form_instance
SET value_snapshot = #{update.valueSnapshot},
    updater = #{update.updater},
    update_time = CURRENT_TIMESTAMP(3),
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND preparation_id = #{update.preparationId}
  AND item_id = #{update.itemId}
  AND id = #{update.formInstanceId}
  AND version = #{update.expectedVersion}
  AND status_code = 'DRAFT'
  AND frozen_at IS NULL

UPDATE sol_dynamic_form_instance
SET status_code = 'FROZEN',
    frozen_at = #{update.frozenAt},
    frozen_by = #{update.frozenBy},
    updater = #{update.updater},
    update_time = CURRENT_TIMESTAMP(3),
    version = version + 1
WHERE tenant_id = #{update.tenantId}
  AND preparation_id = #{update.preparationId}
  AND item_id = #{update.itemId}
  AND id = #{update.formInstanceId}
  AND version = #{update.expectedVersion}
  AND status_code = 'DRAFT'
  AND frozen_at IS NULL
